/**
 * Every rect, anchor, and scroll range of the 06:00 sunrise footer. Change numbers here, never in the component.
 *
 * Coordinates are percentages of the stage: `x`/`w` of its width, `y`/`h` of its height. Desktop stage = 16:9
 * (2560×1440 reference px), anchored to the bottom of the section behind the footer bar. Mobile stage = a square scene
 * band (1080×1080) in the flow, right above the footer bar. Layers are placed by their **full master canvas**
 * (docs/art/sunrise/*.png); the optimized assets are cropped to their content and ./art.ts (generated by
 * tools/build-assets.mjs) says where, so re-cropping or swapping art of the same canvas needs no change here.
 *
 * Props stand on the painted path: `PATH_SURFACE` traces the sand line in path master pixels, and the coffee rock and the
 * closed laptop are placed by an x position, with y read from that line.
 *
 * Scroll: `--sunrise` goes 0 → 1 while the section scrolls in (top edge at the viewport bottom → the page end).
 */
import { ART_BOXES, type ArtBox } from './art.ts';

export interface Rect {
	x: number;
	y: number;
	w: number;
	h: number;
}

export type Breakpoint = 'desktop' | 'mobile';

const STAGE: Record<Breakpoint, { width: number; height: number }> = {
	desktop: { width: 2560, height: 1440 },
	mobile: { width: 1080, height: 1080 }
};

/** The sand line of `sunrise-cliff-path.png` (master px, left → right), where the props touch down. */
const PATH_SURFACE: [number, number][] = [
	[0, 118],
	[640, 196],
	[1280, 268],
	[1920, 330],
	[2560, 386]
];

/** Coffee master (600×600): where the rock meets the ground, and the box above the cup mouth for the steam. */
const COFFEE_BASE = { x: 300, y: 530 };
const COFFEE_STEAM: Rect = { x: 222, y: -230, w: 150, h: 420 };
/** Laptop master (docs/art/sunrise/sunrise-laptop.png, 1400×700, the closed laptop on its own flat rock): where the rock's
 *  broad base meets the ground (a little above its rounded lowest point, so it sits in the path), and the lid's sunlit
 *  right edge for the glint. */
const LAPTOP_BASE = { x: 670, y: 588 };
const LAPTOP_GLINT: Rect = { x: 1000, y: 150, w: 240, h: 220 };
/** The sun baked into each sky plate (fraction of the plate), see docs/art/sunrise/README.md. */
const SKY_SUN: Record<Breakpoint, { x: number; y: number }> = { desktop: { x: 0.79, y: 0.68 }, mobile: { x: 0.78, y: 0.5 } };

/** A layer's full master canvas on the stage: left/top and width in stage %, height follows the canvas aspect. */
interface Place {
	x: number;
	y: number;
	w: number;
}

interface Placement {
	/** Sky plate; the sun glow rides along with it. */
	sky: Place;
	valley: Place;
	cliffPath: Place;
	/** Coffee rock: center x on the path and canvas width; `sink` pushes it into the ground (stage %). */
	coffee: { x: number; w: number; sink: number };
	/** Closed laptop next to the cup: like the coffee. */
	laptop: { x: number; w: number; sink: number };
	/** Diameter of the warm glow over the baked sun (stage % of width). */
	sunGlow: number;
}

const PLACEMENT: Record<Breakpoint, Placement> = {
	desktop: {
		sky: { x: 0, y: -10, w: 100 },
		valley: { x: 0, y: 29.2, w: 100 },
		cliffPath: { x: -2, y: 46.5, w: 104 },
		coffee: { x: 9.5, w: 8.6, sink: 0.6 },
		// body ≈ 2.2 × the mug's width (the masters' px scale: coffee ÷ 1.286, docs/art/sunrise/README.md)
		laptop: { x: 22, w: 15.6, sink: 0.6 },
		sunGlow: 22
	},
	mobile: {
		sky: { x: 0, y: -66, w: 100 },
		valley: { x: -82, y: 26, w: 205 },
		cliffPath: { x: -14, y: 52, w: 150 },
		coffee: { x: 12, w: 22, sink: 1 },
		// smaller than the desktop ratio, so it doesn't dominate the narrow scene
		laptop: { x: 37, w: 33, sink: 1 },
		sunGlow: 46
	}
};

const stageAspect = (bp: Breakpoint) => STAGE[bp].width / STAGE[bp].height;
const round = (value: number) => Math.round(value * 1000) / 1000;

/** The canvas rect of a layer (stage %). */
function canvasRect(bp: Breakpoint, place: Place, box: ArtBox): Rect {
	return { ...place, h: place.w * (box.canvas.height / box.canvas.width) * stageAspect(bp) };
}

/** A sub-rect, given in master px, of a canvas rect (stage %). */
function subRect(canvas: Rect, box: ArtBox, sub: Rect): Rect {
	const sx = canvas.w / box.canvas.width;
	const sy = canvas.h / box.canvas.height;
	return { x: canvas.x + sub.x * sx, y: canvas.y + sub.y * sy, w: sub.w * sx, h: sub.h * sy };
}

/** The rect of the cropped asset inside its canvas rect (stage %). */
const cropRect = (canvas: Rect, box: ArtBox): Rect => subRect(canvas, box, { x: box.crop.x, y: box.crop.y, w: box.crop.width, h: box.crop.height });

/** y (stage %) of the walkable path at stage x. */
function groundAt(path: Rect, x: number): number {
	const box = ART_BOXES.cliffPath;
	const mx = Math.min(box.canvas.width, Math.max(0, ((x - path.x) / path.w) * box.canvas.width));
	const index = Math.min(
		PATH_SURFACE.length - 1,
		Math.max(
			1,
			PATH_SURFACE.findIndex(([px]) => px >= mx)
		)
	);
	const [x0, y0] = PATH_SURFACE[index - 1]!;
	const [x1, y1] = PATH_SURFACE[index]!;
	const my = y0 + ((mx - x0) / (x1 - x0)) * (y1 - y0);
	return path.y + (my / box.canvas.height) * path.h;
}

/** Canvas rect of a layer that stands on the path: master point `anchor` lands at stage (x, ground + sink). */
function standOn(bp: Breakpoint, path: Rect, box: ArtBox, anchor: { x: number; y: number }, at: { x: number; w: number; sink: number }): Rect {
	const h = at.w * (box.canvas.height / box.canvas.width) * stageAspect(bp);
	const ground = groundAt(path, at.x) + at.sink;
	return { x: at.x - at.w * (anchor.x / box.canvas.width), y: ground - h * (anchor.y / box.canvas.height), w: at.w, h };
}

export interface SunriseLayout {
	sky: Rect;
	/** Sun glow in % of the sky rect. */
	sunGlow: Rect;
	valley: Rect;
	cliffPath: Rect;
	coffee: Rect;
	steam: Rect;
	laptop: Rect;
	/** Warm glint on the lid edge (stage %). */
	laptopGlint: Rect;
}

function build(bp: Breakpoint): SunriseLayout {
	const place = PLACEMENT[bp];
	const skyBox = ART_BOXES[bp === 'desktop' ? 'sky' : 'skyMobile'];
	const sky = cropRect(canvasRect(bp, place.sky, skyBox), skyBox);
	// a circle of `sunGlow` stage-% width around the baked sun, in % of the sky rect
	const glowW = (place.sunGlow / sky.w) * 100;
	const glowH = ((place.sunGlow * stageAspect(bp)) / sky.h) * 100;
	const pathCanvas = canvasRect(bp, place.cliffPath, ART_BOXES.cliffPath);
	const coffeeCanvas = standOn(bp, pathCanvas, ART_BOXES.coffee, COFFEE_BASE, place.coffee);
	const laptopCanvas = standOn(bp, pathCanvas, ART_BOXES.laptop, LAPTOP_BASE, place.laptop);
	return {
		sky,
		sunGlow: { x: SKY_SUN[bp].x * 100 - glowW / 2, y: SKY_SUN[bp].y * 100 - glowH / 2, w: glowW, h: glowH },
		valley: cropRect(canvasRect(bp, place.valley, ART_BOXES.valley), ART_BOXES.valley),
		cliffPath: cropRect(pathCanvas, ART_BOXES.cliffPath),
		coffee: cropRect(coffeeCanvas, ART_BOXES.coffee),
		steam: subRect(coffeeCanvas, ART_BOXES.coffee, COFFEE_STEAM),
		laptop: cropRect(laptopCanvas, ART_BOXES.laptop),
		laptopGlint: subRect(laptopCanvas, ART_BOXES.laptop, LAPTOP_GLINT)
	};
}

export const SUNRISE_LAYOUT: Record<Breakpoint, SunriseLayout> = { desktop: build('desktop'), mobile: build('mobile') };

const pct = (value: number) => `${round(value)}%`;

/** Inline CSS vars for an element placed on both stages: `--dx --dy --dw --dh` (desktop) and `--mx …` (mobile). */
export function placeVars(desktop: Rect, mobile: Rect): string {
	return [
		`--dx: ${pct(desktop.x)}; --dy: ${pct(desktop.y)}; --dw: ${pct(desktop.w)}; --dh: ${pct(desktop.h)}`,
		`--mx: ${pct(mobile.x)}; --my: ${pct(mobile.y)}; --mw: ${pct(mobile.w)}; --mh: ${pct(mobile.h)}`
	].join('; ');
}

